mapper.update:
UPDATE lostfound
SET status = #{status}
WHERE id = #{id}
  AND status = #{currentStatus}

UPDATE lostfound_claim
SET status = #{status}
WHERE id = #{id}
  AND lostfound_id = #{lostfoundId}
  AND status = 'PENDING'

UPDATE lostfound_claim
SET status = 'REJECTED'
WHERE lostfound_id = #{lostfoundId}
  AND id != #{approvedClaimId}
  AND status = 'PENDING'

